interface Transaction {
  id: string;
  kind: 'debit' | 'credit';
  status: 'completed' | 'pending';
  category: string;
  amountMinor: number; // cents/paise; single currency in this demo
  postedAt: string;    // normalized ISO timestamp
}
const transactions: Transaction[] = [
  { id: 't1', kind: 'debit', status: 'completed', category: 'food', amountMinor: 1250, postedAt: '2026-01-03T10:00:00Z' },
  { id: 't2', kind: 'credit', status: 'completed', category: 'salary', amountMinor: 50000, postedAt: '2026-01-02T10:00:00Z' },
  { id: 't3', kind: 'debit', status: 'completed', category: 'food', amountMinor: 750, postedAt: '2026-01-04T10:00:00Z' },
  { id: 't4', kind: 'debit', status: 'pending', category: 'travel', amountMinor: 2200, postedAt: '2026-01-05T10:00:00Z' }
];

const completedDebits = transactions.filter(t => t.kind === 'debit' && t.status === 'completed');
const newestFirst = [...completedDebits].sort((a, b) =>
  Date.parse(b.postedAt) - Date.parse(a.postedAt)
);
const rows = newestFirst.map(({ id, category, amountMinor }) => ({
  id, category, amountMinor
}));
const byCategory = completedDebits.reduce<Record<string, number>>((totals, t) => {
  totals[t.category] = (totals[t.category] ?? 0) + t.amountMinor;
  return totals;
}, {});
console.log(rows.map(r => r.id)); // ['t3', 't1']
console.log(byCategory); // { food: 2000 }
console.log(transactions[0].id); // Original array order unchanged
